/* Persistence runs through IndexedDB — it's async (so the call sites below don't
   change), it survives reinstalling nothing, and Chrome gives it a far bigger
   quota than localStorage. localStorage is kept as a fallback for the rare build
   where IndexedDB is unavailable. The log lives on this device: use Export in ⚙
   to move it or back it up. */
let STORAGE_OK = true;
let warnedStorage = false;

const DB_NAME = 'ironlog', DB_STORE = 'kv';
let dbPromise = null;

function openDB() {
  if (dbPromise) return dbPromise;
  dbPromise = new Promise((res, rej) => {
    if (!self.indexedDB) return rej(new Error('no indexedDB'));
    const req = indexedDB.open(DB_NAME, 1);
    req.onupgradeneeded = () => {
      if (!req.result.objectStoreNames.contains(DB_STORE)) req.result.createObjectStore(DB_STORE);
    };
    req.onsuccess = () => res(req.result);
    req.onerror = () => rej(req.error);
    req.onblocked = () => rej(new Error('blocked'));
  });
  return dbPromise;
}

export function idb(mode, fn) {
  return openDB().then(db => new Promise((res, rej) => {
    const tx = db.transaction(DB_STORE, mode);
    const r = fn(tx.objectStore(DB_STORE));
    r.onsuccess = () => res(r.result);
    r.onerror = () => rej(r.error);
    tx.onabort = () => rej(tx.error || new Error('aborted'));
  }));
}

/* A read that fails is not the same as nothing stored (bug sweep 1.4): the
   app used to open as a fresh install either way, and the next save could
   land on top of the real log once IndexedDB answered again. So a failed
   read with no fallback copy throws when `strict` (the log itself, at boot),
   and boot shows the rescue screen. Skins, photos and clips keep the old
   answer of "nothing there". A browser with no IndexedDB at all still runs
   on localStorage as before. */
export async function storeGet(k, strict) {
  let failed = null;
  try {
    const v = await idb('readonly', st => st.get(k));
    if (v != null) return v;          // undefined = fresh install, not an error
  } catch (e) { failed = e; }
  let ls = null;
  try { ls = localStorage.getItem(k); } catch (e) { /* blocked: same as empty */ }
  if (strict && ls == null && failed && self.indexedDB) throw new Error(`This phone's storage didn't answer (${failed.message || failed.name || 'read failed'})`);
  return ls;
}

export async function storePut(k, v) {
  let ok = false;
  try { await idb('readwrite', st => st.put(v, k)); ok = true; }
  catch (e) {
    try { localStorage.setItem(k, v); ok = true; }   // only mirror when IDB is down
    catch (e2) { ok = false; }
  }
  STORAGE_OK = ok;
  if (!ok && !warnedStorage) {
    warnedStorage = true;
    toast('⚠ Storage is not responding — your log may not survive a refresh. Export from ⚙ to keep it.');
  }
  return ok;
}

/* Ask Android not to evict the log when storage runs low. Granted automatically
   once the app is installed to the home screen. */
/* ---------------- storage safety (roadmap A3) ----------------
   Chrome may clear an origin's IndexedDB when the phone runs short of space —
   unless the origin is "persisted". Chrome decides on its own (an installed,
   used app usually qualifies), so ask once there is a logged session worth
   protecting, and show the answer in Settings. Until backups go to the user's
   own drive (B6), a JSON export is the only copy, so the Home page nudges when
   the last one is over two weeks old. */
export const persist = { state: 'unknown', usage: 0, quota: 0 };   // granted | denied | unsupported | unknown
export async function storageStatus() {
  try {
    if (!(navigator.storage && navigator.storage.persisted)) { persist.state = 'unsupported'; return persist; }
    persist.state = (await navigator.storage.persisted()) ? 'granted' : 'denied';
    if (navigator.storage.estimate) {
      const e = await navigator.storage.estimate();
      persist.usage = e.usage || 0; persist.quota = e.quota || 0;
    }
  } catch (e) { persist.state = 'unsupported'; }
  return persist;
}
export async function requestPersistence(force) {
  try {
    if (!(navigator.storage && navigator.storage.persist)) { persist.state = 'unsupported'; return persist.state; }
    if (await navigator.storage.persisted()) { persist.state = 'granted'; return persist.state; }
    // nothing worth protecting yet: don't spend the ask
    if (!force && !S.workouts.some(w => w.status === 'completed')) return persist.state;
    persist.state = (await navigator.storage.persist()) ? 'granted' : 'denied';
    S.settings.persistAskedAt = Date.now(); save();
  } catch (e) { persist.state = 'unsupported'; }
  return persist.state;
}
export const BACKUP_EVERY = 14 * 864e5, BACKUP_SNOOZE = 7 * 864e5;
/* When the last backup was, or null. A log with no backup at all counts from
   its first completed session, so a new user isn't nagged on day one. */
function backupDue() {
  const done = S.workouts.filter(w => w.status === 'completed');
  if (!done.length) return null;
  const now = Date.now(), st = S.settings;
  if (st.backupSnoozeUntil && now < st.backupSnoozeUntil) return null;
  const first = Math.min(...done.map(w => parseISO(w.date).getTime()));
  // a Drive sync is a backup too (B6)
  const last = Math.max(st.lastExportAt || 0, syncMeta().lastSyncAt || 0) || null;
  const since = last || first;
  /* Connected to Drive, backing up is one tap — so the reminder comes after 3 days, not 14. */
  return now - since > (syncMeta().connected ? 3 * 864e5 : BACKUP_EVERY) ? { last, days: Math.floor((now - since) / 864e5), drive: !!syncMeta().connected } : null;
}
