export function backupCard() {
  if (S.active) return '';           // never during a workout
  const due = backupDue();
  if (!due) return '';
  return `<div class="card" id="backupCard" style="border-color:var(--gold)">
    <div class="row between" style="gap:10px;align-items:center">
      <div class="grow"><div style="font-weight:700">Back up your log</div>
        <div class="sub">${due.last ? `Last backup ${due.days} days ago.` : 'No backup yet.'} ${due.drive ? 'Sync to your Google Drive to keep it safe.' : 'Your log lives only on this phone — save a copy to Drive or your files.'}</div></div>
      <div class="row" style="gap:6px;flex-direction:column">
        <button class="btn sm primary" id="backupNow">${due.drive ? 'Sync' : 'Back up'}</button>
        <button class="btn xs ghost" id="backupLater">Not now</button>
      </div>
    </div>
  </div>`;
}
/* The storage + backup line in Settings, redrawn in place after an export or
   an ask, so the modal doesn't jump back to the top. */
export function storageLine() {
  return `<div class="row between" style="gap:10px;align-items:center;margin-bottom:10px" id="stStorage">
        <div class="grow sub">${persist.state === 'granted' ? '✓ <b>Storage protected</b> — Chrome won\'t clear it when space runs low.'
          : persist.state === 'denied' ? '<b>Storage not protected</b> — Chrome may clear it if the phone runs short of space. Installing the app and using it regularly usually earns protection; keep backups until then.'
            : persist.state === 'unsupported' ? 'This browser doesn\'t report storage protection. Keep backups.' : 'Checking storage…'}
          ${persist.usage ? `<br>Using ${fmtBytes(persist.usage)}.` : ''}
          <br>${S.settings.lastExportAt ? `Last backup ${relDay(iso(new Date(S.settings.lastExportAt))).toLowerCase()}.` : 'No backup yet.'}</div>
        ${persist.state === 'denied' ? '<button class="btn xs" id="stPersist">Ask again</button>' : ''}
      </div>`;
}
export function refreshStorageLine(bg) {
  const el = $('#stStorage', bg);
  if (!el) return;
  el.outerHTML = storageLine();
  const sp = $('#stPersist', bg);
  if (sp) sp.onclick = async () => {
    const r = await requestPersistence(true);
    await storageStatus();
    toast(r === 'granted' ? 'Storage is now protected' : 'Chrome said no for now — it decides by how much the app is used', r === 'granted' ? 'green' : '');
    refreshStorageLine(bg);
  };
}
/* ============================================================
   DRIVE SYNC — roadmap B6, r&d/specs/drive-sync-spec.md
   One file in the user's own Google Drive, merged by every device that
   connects. drive.file scope: Ironlog sees only the files it made. No server:
   the browser talks to Google directly, and the token lives in memory.
   ============================================================ */
const GOOGLE_CLIENT_ID = '321532083266-jg1rrna34dq5mcsd28h7g346u7sndl59.apps.googleusercontent.com';   // public by design; tied to the deployed origin (spec: Setup). Settings can override
const DRIVE_SCOPE = 'https://www.googleapis.com/auth/drive.file';
const SYNC_FILE = 'Ironlog backup.json', SYNC_FORMAT = 'ironlog-sync', SYNC_V = 1;
// collection -> how a record is keyed
const SYNC_SETS = {
  workouts: x => x.id, misses: x => x.id, goals: x => x.id, meets: x => x.id, imports: x => x.id,
  checkins: x => x.date, measures: x => x.id, calipers: x => x.id, mobTests: x => x.id, bp: x => x.id, glucose: x => x.id, fitTests: x => x.id,
  customEx: x => (typeof x === 'string' ? x : JSON.stringify(x)), programs: x => String(x),
  /* The lifter's own exercises. Left out until 0.90.7, so a phone restored
     from Drive had the sessions but not the names (bug sweep 1.6). */
  customMovements: x => x.id,
  places: x => x.id,
};
const SYNC_MAPS = ['exAliases', 'programStarts', 'coach', 'programNames', 'exNotes', 'slewProfiles'];
/* Two settings sync record by record like the collections (bug sweep 4.5):
   places (kit, bars and plates per gym, keyed by id) and the bar-speed
   calibration (slewProfiles, keyed by lift). They live in S.settings on the
   phone and travel as their own collections in the file, with deletes and
   the newest-wins rule. Every other setting stays per phone (spec §4). */
const SYNC_FROM_SETTINGS = ['places', 'slewProfiles'];
const SYNC_LOCAL_SETTINGS = ['lastSeenVersion', 'backupSnoozeUntil', 'lastExportAt'];

/* Device-only bookkeeping, outside S so it never syncs itself:
   { connected, fileId, lastSyncAt, known: { collection: [keys] }, includeKey, clientId } */
export function syncMeta() { try { return JSON.parse(localStorage.getItem('ironlog.sync') || '{}') || {}; } catch (e) { return {}; } }
function setSyncMeta(m) { try { localStorage.setItem('ironlog.sync', JSON.stringify(m)); } catch (e) { /* storage blocked: sync still works, just forgets */ } }
function driveClientId() { return syncMeta().clientId || GOOGLE_CLIENT_ID; }
/* After the whole log is swapped (a backup imported, or that import undone),
   what this phone "knew" at its last sync no longer describes it. Left in
   place, every record the backup doesn't have would read as deleted here, and
   the next sync would remove up to five of them from Drive and from every
   other phone without asking (bug sweep 1.5). Forgotten, the next sync is a
   plain merge: nothing is treated as deleted. */
function syncForgetKnown() { const m = syncMeta(); if (m.known) { delete m.known; setSyncMeta(m); } }
/* When a record last changed: the newest of its stamps. (It used to take the
   first one present, so a session moved and later edited kept the move's time.) */
function stampOf(x) { return x && typeof x === 'object' ? Math.max(+x.mt || 0, +x.edited || 0, +x.end || 0, +x.start || 0) : 0; }

function syncLocalData() {
  const d = {};
  const src = k => SYNC_FROM_SETTINGS.includes(k) ? S.settings[k] : S[k];
  Object.keys(SYNC_SETS).forEach(k => { d[k] = src(k) || []; });
  SYNC_MAPS.forEach(k => { d[k] = src(k) || {}; });
  return d;
}
function syncKnown(d) {
  const k = {};
  Object.entries(SYNC_SETS).forEach(([c, key]) => { k[c] = (d[c] || []).map(key); });
  SYNC_MAPS.forEach(c => { k[c] = Object.keys(d[c] || {}); });
  return k;
}

/* The merge. Pure: local and remote data, the remote tombstones, the keys this
   device knew at its last sync. Returns the merged data, the tombstones to
   write, and what this device deleted (for the safety valve). Local wins
   ties; nothing that exists only here is ever dropped unless this device
   deleted it or another device deleted it later than it was last changed. */
function mergeSync(local, remote, remoteTomb, known, now, opts = {}) {
  const tomb = structuredClone(remoteTomb || {});
  const mark = (c, id, t) => { const m = tomb[c] = tomb[c] || {}; if (!(m[id] >= t)) m[id] = t; };
  const localDeletes = [];
  const restore = !(local.workouts || []).length;   // an empty device is restoring, not deleting
  const colls = [...Object.keys(SYNC_SETS), ...SYNC_MAPS];
  if (!restore && !opts.keepMissing) colls.forEach(c => {
    const have = new Set(SYNC_MAPS.includes(c) ? Object.keys(local[c] || {}) : (local[c] || []).map(SYNC_SETS[c]));
    ((known || {})[c] || []).forEach(id => { if (!have.has(id)) { mark(c, id, now); localDeletes.push([c, id]); } });
  });
  const out = {};
  /* Here but not known at the last sync: it was made on this device since.
     That beats a delete marker whatever its stamp — a program removed and put
     back, a check-in deleted and re-entered, an alias, a coach plan after
     Forget — because most of those carry no time at all, and "no time" used to
     lose to every marker: the next sync deleted them again (bug sweep 1.1). */
  const knownSets = {};
  const madeHere = (c, id) => {
    if (!known) return true;                                 // never synced: everything here is this device's own
    const s = knownSets[c] || (knownSets[c] = new Set((known[c] || []).map(String)));
    return !s.has(String(id));
  };
  const pick = (c, id, l, r) => {
    const t = tomb[c] && tomb[c][id];
    const v = l !== undefined && r !== undefined ? (stampOf(r) > stampOf(l) ? r : l) : l !== undefined ? l : r;
    if (t != null && l !== undefined && madeHere(c, id)) { delete tomb[c][id]; return v; }
    if (t != null && !(stampOf(v) > t)) return undefined;   // deleted, and not changed since
    if (t != null) delete tomb[c][id];                       // changed after the delete: it's back
    return v;
  };
  Object.entries(SYNC_SETS).forEach(([c, key]) => {
    const L = new Map((local[c] || []).map(x => [key(x), x]));
    const R = new Map(((remote || {})[c] || []).map(x => [key(x), x]));
    const ids = [...new Set([...L.keys(), ...R.keys()])];
    out[c] = ids.map(id => pick(c, id, L.get(id), R.get(id))).filter(x => x !== undefined);
  });
  SYNC_MAPS.forEach(c => {
    const L = local[c] || {}, R = (remote || {})[c] || {};
    out[c] = {};
    [...new Set([...Object.keys(L), ...Object.keys(R)])].forEach(id => {
      const v = pick(c, id, L[id], R[id]);
      if (v !== undefined) out[c][id] = v;
    });
  });
  return { data: out, tomb, localDeletes };
}

/* ---- Google sign-in and Drive, loaded only when asked for ---- */
let driveTok = null;   // { token, exp } — memory only
export function loadGis() {
  return new Promise((res, rej) => {
    if (window.google && window.google.accounts && window.google.accounts.oauth2) return res();
    const s = document.createElement('script');
    s.src = 'https://accounts.google.com/gsi/client'; s.async = true;
    s.onload = () => res(); s.onerror = () => rej(new Error('Couldn\'t reach Google — are you online?'));
    document.head.appendChild(s);
  });
}
function driveTokenValid() { return !!(driveTok && driveTok.exp > Date.now() + 60e3); }
async function driveToken(interactive) {
  if (driveTokenValid()) return driveTok.token;
  if (!interactive) return null;
  const cid = driveClientId();
  if (!cid) throw new Error('Drive backup isn\'t set up for this copy of Ironlog yet');
  await loadGis();
  return new Promise((res, rej) => {
    const tc = window.google.accounts.oauth2.initTokenClient({
      client_id: cid, scope: DRIVE_SCOPE,
      callback: r => {
        if (r.error) return rej(new Error(r.error_description || r.error));
        if (!window.google.accounts.oauth2.hasGrantedAllScopes(r, DRIVE_SCOPE)) return rej(new Error('Drive access wasn\'t allowed'));
        driveTok = { token: r.access_token, exp: Date.now() + (+r.expires_in || 3600) * 1000 };
        res(driveTok.token);
      },
      error_callback: e => rej(new Error(e && e.type === 'popup_closed' ? 'Sign-in was closed' : 'Sign-in didn\'t finish')),
    });
    tc.requestAccessToken({ prompt: syncMeta().connected ? '' : 'consent' });
  });
}
